const MS_PER_UPDATE = 1000 / 60;
const MAX_ELAPSED = 250;
let previous = performance.now();
let lag = 0;

function frame(now) {
  let elapsed = Math.min(now - previous, MAX_ELAPSED); // tab was hidden?
  previous = now;
  lag += elapsed;

  processInput();
  while (lag >= MS_PER_UPDATE) {
    update();
    lag -= MS_PER_UPDATE;
  }
  render(lag / MS_PER_UPDATE);
  requestAnimationFrame(frame);   // hand control back to the browser
}
