const double MS_PER_UPDATE = 1000.0 / 60.0;
const int MAX_STEPS = 5;

double previous = getCurrentTime();
double lag = 0.0;
while (true) {
  double current = getCurrentTime();
  lag += current - previous;
  previous = current;

  processInput();
  int steps = 0;
  while (lag >= MS_PER_UPDATE && steps++ < MAX_STEPS) {
    update();               // fixed dt: same on every machine
    lag -= MS_PER_UPDATE;
  }
  render(lag / MS_PER_UPDATE);
}

void Renderer::render(double alpha) {   // alpha = lag / MS_PER_UPDATE
  for (Entity* e : world.entities()) {
    // Book's approach: extrapolate along current velocity.
    Vec2 drawPos = e->pos + e->velocity * (alpha * STEP_SECONDS);

    // Alternative: interpolate between the last two simulated states.
    // Vec2 drawPos = lerp(e->prevPos, e->pos, alpha);

    drawSprite(e->sprite, drawPos);
  }
}

const double TARGET_MS = inMenu ? 1000.0 / 30 : 1000.0 / 60;

while (running) {
  double start = getCurrentTime();
  processInput();
  update();
  if (sceneIsDirty()) render();       // idle screen: skip redraws
  double remaining = start + TARGET_MS - getCurrentTime();
  if (remaining > 0) sleep(remaining); // let the CPU rest -> save battery
}
